import{_ as i,o as s,c as a,ae as t}from"./chunks/framework.Dh1jimFm.js";const d=JSON.parse('{"title":"Linux-Specific Issues","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/linux.md","filePath":"troubleshooting/linux.md"}'),l={name:"troubleshooting/linux.md"};function n(o,e,r,c,p,h){return s(),a("div",null,e[0]||(e[0]=[t('<h1 id="linux-specific-issues" tabindex="-1">Linux-Specific Issues <a class="header-anchor" href="#linux-specific-issues" aria-label="Permalink to &quot;Linux-Specific Issues&quot;">​</a></h1><p>Supervertaler is Linux compatible, but Windows is the primary development platform.</p><h2 id="spellcheck-dictionaries" tabindex="-1">Spellcheck dictionaries <a class="header-anchor" href="#spellcheck-dictionaries" aria-label="Permalink to &quot;Spellcheck dictionaries&quot;">​</a></h2><p>If spellcheck isn’t working, you may need to install Hunspell dictionaries for your language:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hunspell-en-us</span></span></code></pre></div><p>If the dictionary package for your language exists, install it using the language code you need (for example <code>hunspell-de-de</code>, <code>hunspell-nl</code>, etc.).</p><h2 id="stability-tips" tabindex="-1">Stability tips <a class="header-anchor" href="#stability-tips" aria-label="Permalink to &quot;Stability tips&quot;">​</a></h2><p>If you encounter instability:</p><ul><li>Disable spellcheck temporarily</li><li>Disable semantic memory features temporarily</li><li>Use a smaller project to isolate the issue</li></ul><h2 id="crashes-memory-access-violations" tabindex="-1">Crashes / memory access violations <a class="header-anchor" href="#crashes-memory-access-violations" aria-label="Permalink to &quot;Crashes / memory access violations&quot;">​</a></h2><p>Some native dependencies (spellcheck backends, vector search, tokenization libraries) can crash the Python process on certain Linux setups.</p><p>If you see random crashes (segfaults) when interacting with the grid:</p><ol><li>Disable spellcheck and restart</li><li>Disable Supermemory and restart</li><li>Retry on a smaller project</li></ol><p>If that stabilizes the app, re-enable features one by one.</p>',14)]))}const m=i(l,[["render",n]]);export{d as __pageData,m as default};
